"""Twelfth-century institutions, courts and bounded regional contexts."""
import pathlib,json,urllib.parse,re
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'public/data';TAG='support-0.26'
read=lambda f:json.loads((OUT/f).read_text(encoding='utf8'))
save=lambda f,d:(OUT/f).write_text(json.dumps(d,ensure_ascii=False,separators=(',',':'))+'\n',encoding='utf8',newline='\n')
wiki=lambda t:'https://en.wikipedia.org/wiki/'+urllib.parse.quote(t.replace(' ','_'))
clean=lambda s:re.sub(r'(?<=[a-záéíóúñ])(?=[A-ZÁÉÍÓÚÑ0-9])',' ',s)
def main():
 aliases=json.loads((ROOT/'scripts/historical-offices-026-research.json').read_text(encoding='utf8'))['aliases'];key=lambda k:aliases.get(k,k)
 forms=read('governance.json');forms['records']=[r for r in forms['records']if r.get('acquisition')!=TAG]
 for keys,a,b,tags,ref in [('FRA|ENGLAND|SCOTLAND|NAVARRE-KINGDOM|LEON-KINGDOM|DNK|SWE|NORWAY-KINGDOM', 1000, 1099, 'monarchy|kingdom', 'Early Middle Ages'), ('CASTILE-COUNTY', 1000, 1064, 'monarchy|feudal', 'County of Castile'), ('CASTILE-KINGDOM', 1065, 1099, 'monarchy|kingdom', 'Kingdom of Castile'), ('ARAGON-KINGDOM', 1035, 1099, 'monarchy|kingdom', 'Kingdom of Aragon'), ('HUNGARY-KINGDOM', 1000, 1099, 'monarchy|kingdom', 'Kingdom of Hungary'), ('BARCELONA-COUNTY', 1000, 1099, 'monarchy|feudal', 'County of Barcelona'), ('PORTUGAL-COUNTY', 1096, 1099, 'monarchy|feudal', 'County of Portugal'), ('HIST-Q12548', 1000, 1099, 'elective-monarchy|empire|feudal', 'Holy Roman Empire'), ('SAXONY-STEM|BAVARIA-DUCHY|BOHEMIA-DUCHY|NORMANDY-DUCHY', 1000, 1099, 'monarchy|duchy|feudal', 'Stem duchy'), ('BOHEMIA', 1085, 1092, 'monarchy|kingdom', 'Vratislaus II of Bohemia'), ('SAVOY-COUNTY', 1000, 1099, 'monarchy|feudal', 'County of Savoy'), ('SICILY-COUNTY', 1071, 1099, 'monarchy|feudal', 'County of Sicily'), ('POLAND-MEDIEVAL', 1000, 1099, 'monarchy', 'History of Poland'), ('POLAND-MEDIEVAL', 1025, 1031, 'kingdom', 'Kingdom of Poland'), ('POLAND-MEDIEVAL', 1076, 1079, 'kingdom', 'Boleslaw II the Bold'), ('PAPAL-STATES', 1000, 1099, 'elective-monarchy|theocracy', 'Papal States'), ('HIST-Q4948|HIST-Q174306', 1000, 1099, 'republic|oligarchy|city-state', 'Maritime republics'), ('BYZANTINE', 1000, 1099, 'monarchy|empire', 'Byzantine Empire'), ('HIST-Q203817', 1000, 1018, 'monarchy|empire', 'First Bulgarian Empire'), ('HIST-Q2622868', 1000, 1045, 'monarchy|kingdom', 'Bagratid Armenia'), ('CILICIA-PRINCIPALITY', 1080, 1099, 'monarchy|principality', 'Armenian Kingdom of Cilicia'), ('HIST-Q154667', 1008, 1099, 'monarchy|kingdom', 'Kingdom of Georgia'), ('HIST-Q1108445', 1000, 1099, 'monarchy|principality', 'Kievan Rus'), ('NORTHERN-SONG|LIAO', 1000, 1099, 'monarchy|empire', 'History of China'), ('WESTERN-XIA', 1038, 1099, 'monarchy|empire', 'Western Xia'), ('GORYEO', 1000, 1099, 'monarchy|kingdom', 'Goryeo'), ('JPN', 1000, 1099, 'monarchy|feudal', 'Heian period'), ('JPN', 1017, 1068, 'regency', 'Fujiwara no Yorimichi'), ('FATIMID|ABBASID', 1000, 1099, 'monarchy|theocracy', 'Caliphate'), ('HIST-Q171740', 1000, 1031, 'monarchy|theocracy', 'Caliphate of Cordoba'), ('BUYID', 1000, 1055, 'monarchy|emirate', 'Buyid dynasty'), ('HIST-Q3708094', 1037, 1099, 'monarchy|sultanate', 'Seljuk Empire'), ('SELJUK-RUM', 1077, 1099, 'monarchy|sultanate', 'Sultanate of Rum'), ('HIST-Q12844800', 1000, 1099, 'monarchy|sultanate', 'Ghaznavids'), ('HIST-Q75613', 1040, 1099, 'monarchy', 'Almoravid dynasty'), ('HIST-Q55502', 1099, 1099, 'monarchy|feudal', 'Kingdom of Jerusalem'), ('HIST-Q235030|EDESSA', 1098, 1099, 'monarchy|principality|feudal', 'Crusader states'), ('KHM|HIST-Q6806806|HIST-Q888574', 1000, 1099, 'monarchy|kingdom', 'History of Asia')]:
  forms['records'].append(dict(id='form026-'+str(len(forms['records'])),keys=[key(k)for k in keys.split('|')],start=a,end=b,tags=tags.split('|'),source=wiki(ref),note='Clasificación institucional documental, no evaluación moderna ni certificación del control de todo el contorno.',acquisition=TAG))
 save('governance.json',forms)
 cs=read('identities.json')['countries'];places=read('historical-places.json');places['records']=[r for r in places['records']if r.get('acquisition')!=TAG]
 def city(k,n,xy,a=1000,b=1099,aggregate=''):
  k=key(k);aggregate=key(aggregate);v=dict(id='seat026-'+k+'-'+str(a)+'-'+urllib.parse.quote(n,safe='')+('-fallback-'+aggregate if aggregate else ''),keys=[k],name=n,coordinates=xy,start=a,end=b,capital=True,role='Sede histórica · contorno agrupado o pendiente'if aggregate else'Corte o capital histórica',source='https://www.wikidata.org/wiki/'+cs[k]['qid'],note='Sede de referencia, no perímetro urbano ni residencia continua ni gobierno de todas las superficies.',acquisition=TAG)
  if aggregate:v.update(aggregateKey=aggregate,entityName=cs[k]['name'],note='La sede abre la ficha cuando falta su propio contorno; no atribuye la superficie del agregado a esta autoridad.')
  places['records'].append(v)
 for k,n,xy,a,b,ag in [('FRA', 'París', [2.3522, 48.8566], 1000, 1099, ''), ('ENGLAND', 'Winchester · sede regia', [-1.313, 51.061], 1000, 1065, ''), ('ENGLAND', 'Londres', [-0.1278, 51.5074], 1066, 1099, ''), ('ENGLAND', 'Winchester · sede regia', [-1.313, 51.061], 1013, 1042, 'NORTH-SEA-AGGREGATE'), ('DNK', 'Roskilde · sede de referencia', [12.08, 55.642], 1000, 1099, ''), ('DNK', 'Roskilde', [12.08, 55.642], 1013, 1042, 'NORTH-SEA-AGGREGATE'), ('NORWAY-KINGDOM', 'Nidaros · sede de referencia', [10.397, 63.43], 1000, 1099, ''), ('NORWAY-KINGDOM', 'Nidaros', [10.397, 63.43], 1000, 1042, 'NORTH-SEA-AGGREGATE'), ('CASTILE-COUNTY', 'Burgos · corte itinerante', [-3.6969, 42.3439], 1000, 1064, ''), ('CASTILE-KINGDOM', 'Burgos · corte itinerante', [-3.6969, 42.3439], 1065, 1099, ''), ('LEON-KINGDOM', 'León', [-5.5718, 42.5987], 1000, 1099, ''), ('NAVARRE-KINGDOM', 'Pamplona', [-1.6458, 42.8125], 1000, 1099, ''), ('ARAGON-KINGDOM', 'Jaca · corte itinerante', [-0.549, 42.57], 1035, 1099, ''), ('BARCELONA-COUNTY', 'Barcelona', [2.1734, 41.3851], 1000, 1099, ''), ('PORTUGAL-COUNTY', 'Guimarães', [-8.292, 41.443], 1096, 1099, 'LEON-KINGDOM'), ('NORMANDY-DUCHY', 'Ruan', [1.099, 49.443], 1000, 1099, ''), ('BOHEMIA-DUCHY', 'Praga', [14.4208, 50.088], 1000, 1084, ''), ('BOHEMIA', 'Praga', [14.4208, 50.088], 1085, 1092, ''), ('BOHEMIA-DUCHY', 'Praga', [14.4208, 50.088], 1093, 1099, ''), ('SAXONY-STEM', 'Lüneburg · sede de referencia', [10.407, 53.248], 1000, 1099, 'HIST-Q12548'), ('BAVARIA-DUCHY', 'Ratisbona', [12.096, 49.014], 1000, 1099, 'HIST-Q12548'), ('SAVOY-COUNTY', 'Montmélian · sede de referencia', [6.056, 45.502], 1000, 1099, 'HIST-Q12548'), ('HUNGARY-KINGDOM', 'Esztergom', [18.741, 47.792], 1000, 1099, ''), ('BYZANTINE', 'Constantinopla', [28.9784, 41.0082], 1000, 1099, ''), ('PAPAL-STATES', 'Roma', [12.4964, 41.9028], 1000, 1099, ''), ('HIST-Q171740', 'Córdoba', [-4.7794, 37.8882], 1000, 1031, ''), ('HIST-Q2622868', 'Ani', [43.572, 40.507], 1000, 1045, ''), ('CILICIA-PRINCIPALITY', 'Vahka · sede de referencia', [35.927, 37.837], 1080, 1099, ''), ('SICILY-COUNTY', 'Palermo', [13.3614, 38.1157], 1072, 1099, 'NORMAN-ITALY-AGGREGATE'), ('NORTHERN-SONG', 'Kaifeng', [114.3076, 34.797], 1000, 1099, ''), ('LIAO', 'Shangjing · capital superior', [119.38, 43.97], 1000, 1099, ''), ('WESTERN-XIA', 'Xingqing · Yinchuan', [106.23, 38.486], 1038, 1099, ''), ('GORYEO', 'Gaegyeong', [126.554, 37.97], 1000, 1099, ''), ('JPN', 'Kioto · corte imperial', [135.7681, 35.0116], 1000, 1099, ''), ('FATIMID', 'El Cairo', [31.2357, 30.0444], 1000, 1099, ''), ('ABBASID', 'Bagdad', [44.3661, 33.3152], 1000, 1055, 'BUYID'), ('ABBASID', 'Bagdad', [44.3661, 33.3152], 1055, 1099, 'HIST-Q3708094'), ('HIST-Q12844800', 'Ghazni', [68.42, 33.55], 1000, 1099, ''), ('KHM', 'Angkor', [103.867, 13.412], 1000, 1099, ''), ('HIST-Q888574', 'Pagan', [94.86, 21.17], 1044, 1099, ''), ('HIST-Q55502', 'Jerusalén', [35.231, 31.778], 1099, 1099, ''), ('HIST-Q235030', 'Antioquía', [36.16, 36.2], 1098, 1099, ''), ('EDESSA', 'Edesa', [38.795, 37.159], 1098, 1099, '')]:city(k,n,xy,a,b,ag)
 city('BOHEMIA-DUCHY','Praga',[14.4208,50.088],1000,1084,'HIST-Q12548')
 city('BOHEMIA','Praga',[14.4208,50.088],1085,1092,'HIST-Q12548')
 city('BOHEMIA-DUCHY','Praga',[14.4208,50.088],1093,1099,'HIST-Q12548')
 save('historical-places.json',places)
 context=read('historical-context.json');history=read('country-history.json');points=read('conflict-points.geojson')
 for d,f in[(context,'events'),(history,'records')]:d[f]=[v for v in d[f]if not v['id'].startswith('review026-')]
 points['features']=[v for v in points['features']if not str(v['id']).startswith('review026-')]
 rows=[('england', 'conflict', 'ENGLAND|DNK|NORWAY-KINGDOM', 1013, 1042, 'Conquistas danesas y restauraciones inglesas', 'Etelredo es restaurado en1014; Edmundo yCanuto disputan el gobierno en1016. Los accesos danés, noruego e inglés deCanuto son distintos. Las coronas unidas no forman un Estado nacional uniforme.', 'https://www.english-heritage.org.uk/learn/story-of-england/early-medieval/introduction/', [-0.1278, 51.5074]), ('hastings', 'conflict', 'ENGLAND|NORMANDY-DUCHY|NORWAY-KINGDOM', 1066, 1066, 'Stamford Bridge, Hastings y conquista normanda', 'Eduardo, Harold, Edgar yGuillermo tienen funciones y fechas distintas. StamfordBridge25septiembre, Hastings14octubre y coronación25diciembre no son un solo cambio instantáneo de frontera.', 'https://historicengland.org.uk/listing/the-list/list-entry/1000013', [0.487, 50.912]), ('france', 'institution', 'FRA', 1000, 1099, 'Realeza capeta y poderes principescos', 'RobertoII, EnriqueI yFelipeI son reyes de los francos. El agregado francés no significa administración uniforme de los condados y ducados ni justifica una bandera de lises posterior.', 'Early Capetians', None), ('iberia', 'institution', 'CASTILE-COUNTY|CASTILE-KINGDOM|LEON-KINGDOM|NAVARRE-KINGDOM|ARAGON-KINGDOM', 1029, 1072, 'Sucesiones deFernando y reinos ibéricos', 'Condado castellano y realeza leonesa son funciones distintas. La sucesión de1065 separa coronas; SanchoII yAlfonsoVI tienen accesos y restauraciones propios. El origen del título real castellano presenta interpretaciones historiográficas.', 'https://riubu.ubu.es/bitstream/10259/6273/1/0211_8998_n250_p289-312.pdf', None), ('cordoba', 'conflict', 'HIST-Q171740|HIST-Q276951', 1009, 1031, 'Fitna y final del califato deCórdoba', 'Restauraciones deHishamII, califas rivales y poderes amiríes no equivalen a control uniforme. La abolición del califato en1031 se distingue de las taifas sucesoras.', 'https://tesauros.cultura.gob.es/tesauros/contextosculturales/1006745', [-4.7794, 37.8882]), ('almoravid', 'conflict', 'HIST-Q75613|CASTILE-KINGDOM|LEON-KINGDOM|HIST-Q276951', 1086, 1091, 'Intervención almorávide y anexión de taifas', 'Sagrajas1086 y anexiones posteriores son fases distintas. No toda ayuda militar implica anexión inmediata ni gobierno uniforme sobre todos los territorios.', 'Battle of Sagrajas', [-6.99, 38.98]), ('investiture', 'conflict', 'HIST-Q12548|PAPAL-STATES|SAXONY-STEM', 1075, 1099, 'Querella de las investiduras y realeza rival', 'EnriqueIV, GregorioVII y candidatos rivales tienen funciones distintas. Canossa1077 y coronación imperial1084 no son equivalentes a un acceso real único.', 'Investiture Controversy', [10.457, 44.577]), ('bohemia', 'institution', 'BOHEMIA-DUCHY|BOHEMIA|HIST-Q12548', 1085, 1092, 'Título real personal deVratislaoII', 'La dignidad real no convierte todo el siglo en reino hereditario. Al terminar este reinado se conserva la fase ducal posterior.', 'Vratislaus II of Bohemia', None), ('bulgaria', 'conflict', 'BYZANTINE|HIST-Q203817', 1000, 1018, 'Conflicto búlgaro-bizantino', 'BasilioII y los zares búlgaros tienen autoridades distintas. La conquista culmina en1018; los levantamientos posteriores no prolongan una serie imperial continua.', 'Byzantine conquest of Bulgaria', [23.014, 41.365]), ('byzantium', 'institution', 'BYZANTINE', 1028, 1081, 'Emperatrices, regencias y sucesión bizantina', 'Zoe yTeodora tienen etapas reinantes y consortes distintas. Eudoxia actúa como regente; MiguelVII es coemperador antes de1071. No se prolonga aZoe después de su muerte en1050.', 'Zoe Porphyrogenita', None), ('manzikert', 'conflict', 'BYZANTINE|HIST-Q3708094', 1071, 1071, 'Manzikert y crisis deAnatolia', 'La batalla de26agosto1071 y las guerras civiles posteriores son procesos distintos. La victoria selyúcida no representa la anexión instantánea de todaAnatolia.', 'https://doi.org/10.1093/obo/9780199791279-0063', [42.536, 39.142]), ('crusade', 'conflict', 'BYZANTINE|HIST-Q3708094|SELJUK-RUM|HIST-Q55502|HIST-Q235030|EDESSA|FATIMID', 1096, 1099, 'Primera Cruzada y formación de poderes latinos', 'Edesa yAntioquía aparecen en1098; Jerusalén en1099. Godofredo esDefensor delSantoSepulcro, no rey coronado. No se anticipan estos gobiernos a todo el siglo.', 'https://www.metmuseum.org/de/essays/the-crusades-1095-1291', [35.231, 31.778]), ('armenia', 'institution', 'HIST-Q2622868|CILICIA-PRINCIPALITY|BYZANTINE', 1045, 1099, 'Ani y principado deCilicia', 'Ani es conquistada en1045. La formación del principado deCilicia desde1080 es otra fase y otro ámbito; no se transfiere automáticamente la geometría bagrátida.', 'Bagratid Armenia', None), ('buyid', 'institution', 'BUYID|ABBASID|HIST-Q3708094', 1000, 1055, 'Califas abasíes y poderes buyíes', 'El califa y los emires regionales tienen funciones distintas. La entrada selyúcida enBagdad de1055 no se presenta como nacimiento del califato; se corrige la identificación buyí de la fuente.', 'Buyid dynasty', None), ('china', 'institution', 'NORTHERN-SONG|LIAO|WESTERN-XIA', 1000, 1099, 'Song, Liao y poderes tangut', 'Song yLiao tienen soberanos y territorios propios. Xia adopta el título imperial en1038; Jin ySong delSur no aparecen antes del sigloXII.', 'https://www.metmuseum.org/zh/toah/ht/07/eac', None), ('korea', 'conflict', 'GORYEO|LIAO', 1010, 1019, 'Guerras entreGoryeo yLiao', 'Campañas y restauración de la corte coreana por fases. El triunfo deGwiju de1019 no convierte todos los años de este intervalo en una batalla continua ni permite anticipar el régimen militar de1170.', 'Goryeo–Khitan War', [125.19, 39.97]), ('japan', 'institution', 'JPN', 1000, 1099, 'Emperadores, regentes y gobierno de claustro', 'RegentesFujiwara y emperadores tienen funciones distintas. Shirakawa abdica hacia1086/1087 según el calendario empleado; su gobierno de claustro no es un shogunato.', 'Insei', None), ('ghazna', 'conflict', 'HIST-Q12844800|HIST-Q3708094', 1040, 1040, 'Dandanaqan y retroceso gaznávida', 'La derrota de1040 desplaza el equilibrio regional, pero no extingue inmediatamente la dinastía gaznávida ni todos sus dominios.', 'Battle of Dandanaqan', [61.6, 37.6])]
 for ident,kind,keys,a,b,title,text,ref,xy in rows:
  source=ref if ref.startswith('https://')else wiki(ref);countries=[key(k)for k in keys.split('|')]
  e=dict(id='review026-'+ident,type=kind,countries=countries,title=clean(title),start=f'{a}-01-01',end=f'{b+1}-01-01',text=clean(text),source=source,sourceLabel='Referencia documental · siglo XI',precision=9,note='Contexto parcial de precisión anual; no reconstrucción diaria del control.')
  context['events'].append(e);history['records'].append(dict(id=e['id'],keys=countries,section='history'if kind=='conflict'else'institutions',**{k:v for k,v in e.items()if k not in['id','countries','type']}))
  if xy:points['features'].append(dict(type='Feature',id=e['id'],geometry=dict(type='Point',coordinates=xy),properties=dict(name=e['title'],countries=countries,kind='regional-conflict',start=e['start'],end=f'{b}-12-31',precision=9,source=source,sourceLabel=e['sourceLabel'],note=e['text']+' Punto regional de referencia; no frente, batalla continua ni superficie ocupada.')))
 context['startYear']=1000;history['coverageStart']=1000;save('historical-context.json',context);save('country-history.json',history);save('conflict-points.geojson',points)
 print('Forms',sum(v.get('acquisition')==TAG for v in forms['records']),'seats',sum(v.get('acquisition')==TAG for v in places['records']),'contexts',len(rows),'points',sum(str(v['id']).startswith('review026-')for v in points['features']))
if __name__=='__main__':main()
